package com.sakib.portebo.ui;
import android.content.Intent;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.provider.Settings;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.GridLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.google.android.material.button.MaterialButton;import com.sakib.portebo.R;import com.sakib.portebo.data.AppTierManager;import com.sakib.portebo.lockdown.LockdownManager;import com.sakib.portebo.model.AppItem;import com.sakib.portebo.security.ParentControlManager;import com.sakib.portebo.ui.adapter.HomeAppAdapter;import com.sakib.portebo.ui.adapter.GreylistMonitorAdapter;import com.sakib.portebo.util.AnimUtils;import com.sakib.portebo.service.AlarmScheduler;import com.sakib.portebo.util.BengaliDateFormat;import java.util.ArrayList;import java.util.List;
public class HomeFragment extends Fragment {private RecyclerView rvApps,rvGrey;private HomeAppAdapter home;private GreylistMonitorAdapter grey;private TextView status,diagnostic,nextLockdown;private long lastNextUpdate;private View badge,toggleLockdown;private MaterialButton seeMore;private TextView greySeeMore;private boolean expanded,greyExpanded;private List<AppItem> greyApps=new ArrayList<>();private static final int GREY_COLLAPSED_COUNT=6;private final Handler h=new Handler(Looper.getMainLooper());private final Runnable refresh= new Runnable(){public void run(){if(isAdded()){updateStatus();if(grey!=null)grey.notifyDataSetChanged();h.postDelayed(this,1000);}}};
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle b){View r=i.inflate(R.layout.fragment_home,c,false);rvApps=r.findViewById(R.id.rvHomeApps);rvGrey=r.findViewById(R.id.rvGreylistTrackers);status=r.findViewById(R.id.tvLockdownStatus);diagnostic=r.findViewById(R.id.tvDiagnosticLine);nextLockdown=r.findViewById(R.id.tvNextLockdown);badge=r.findViewById(R.id.tvNoCancelBadge);toggleLockdown=r.findViewById(R.id.btnToggleLockdown);seeMore=r.findViewById(R.id.btnSeeMore);greySeeMore=r.findViewById(R.id.btnGreylistSeeMore);r.findViewById(R.id.btnGoToTiers).setOnClickListener(v->{if(getActivity() instanceof MainActivity)((MainActivity)getActivity()).switchFragment(1);});r.findViewById(R.id.btnTestBatteryOverlay).setOnClickListener(v->startActivity(new Intent(requireContext(),FakeBatteryOverlayActivity.class)));toggleLockdown.setOnClickListener(v->{if(!ParentControlManager.requireEditAccess(requireContext()))return;if(!LockdownManager.isLockdownActive())LockdownManager.startLockdown(requireContext(),60,LockdownManager.LockdownSource.QUICK);updateStatus();});seeMore.setOnClickListener(v->{expanded=!expanded;refreshApps();});greySeeMore.setOnClickListener(v->{greyExpanded=!greyExpanded;showGreyApps();});rvApps.setLayoutManager(new GridLayoutManager(requireContext(),4));home=new HomeAppAdapter(requireContext(),new ArrayList<>());rvApps.setAdapter(home);rvGrey.setLayoutManager(new GridLayoutManager(requireContext(),2));grey=new GreylistMonitorAdapter(requireContext(),new ArrayList<>());rvGrey.setAdapter(grey);return r;}
 private void refreshApps(){List<AppItem>a=AppTierManager.getAllApps();List<AppItem>d=(!expanded&&a.size()>12)?a.subList(0,12):a;home.updateData(d);greyApps=new ArrayList<>();for(AppItem x:a)if(x.getTier()==AppItem.Tier.GREYLIST)greyApps.add(x);showGreyApps();seeMore.setVisibility(a.size()>12?View.VISIBLE:View.GONE);seeMore.setText(expanded?"See less":"See more");}private void showGreyApps(){if(grey==null||greySeeMore==null)return;List<AppItem> visible=(!greyExpanded&&greyApps.size()>GREY_COLLAPSED_COUNT)?greyApps.subList(0,GREY_COLLAPSED_COUNT):greyApps;grey.updateData(new ArrayList<>(visible));greySeeMore.setVisibility(greyApps.size()>GREY_COLLAPSED_COUNT?View.VISIBLE:View.GONE);greySeeMore.setText(greyExpanded?"See less":"See more");}
 private void updateStatus(){boolean active=LockdownManager.isLockdownActive(requireContext());badge.setVisibility(active?View.VISIBLE:View.GONE);status.setText(active?String.format(java.util.Locale.US,"লকডাউন চলছে · বাকি %02d:%02d",LockdownManager.getRemainingSeconds(requireContext())/60,LockdownManager.getRemainingSeconds(requireContext())%60):"লকডাউন বন্ধ। পড়তে বসলে চালু করো।");nextLockdown.setVisibility(active?View.GONE:View.VISIBLE);long now=System.currentTimeMillis();if(!active&&(lastNextUpdate==0||now-lastNextUpdate>=60000)){lastNextUpdate=now;updateNextLockdown(now);}diagnostic.setText("ওভারলে পারমিশন: "+(Settings.canDrawOverlays(requireContext())?"চালু":"বন্ধ"));}
 private void updateNextLockdown(long now){long at=AlarmScheduler.getNextLockdownStart(requireContext());if(at<=0){nextLockdown.setText("কোনো লকডাউন ঠিক করা নেই। রুটিন সেভ করো।");return;}java.util.Calendar target=java.util.Calendar.getInstance(),today=java.util.Calendar.getInstance();target.setTimeInMillis(at);today.setTimeInMillis(now);java.util.Calendar tomorrow=(java.util.Calendar)today.clone();tomorrow.add(java.util.Calendar.DAY_OF_YEAR,1);String day;if(target.get(java.util.Calendar.YEAR)==today.get(java.util.Calendar.YEAR)&&target.get(java.util.Calendar.DAY_OF_YEAR)==today.get(java.util.Calendar.DAY_OF_YEAR))day="আজ";else if(target.get(java.util.Calendar.YEAR)==tomorrow.get(java.util.Calendar.YEAR)&&target.get(java.util.Calendar.DAY_OF_YEAR)==tomorrow.get(java.util.Calendar.DAY_OF_YEAR))day="আগামীকাল";else day=BengaliDateFormat.formatDateOnly(at);int hour=target.get(java.util.Calendar.HOUR_OF_DAY),h=hour%12;if(h==0)h=12;String period=hour<5||hour>=20?"রাত":hour<6?"ভোর":hour<12?"সকাল":hour<16?"দুপুর":hour<18?"বিকেল":"সন্ধ্যা";String clock=com.sakib.portebo.util.BengaliDateFormat.formatTime(hour,target.get(java.util.Calendar.MINUTE));long mins=Math.max(1,(at-now+59999)/60000);String wait=mins<60?com.sakib.portebo.util.BengaliDateFormat.toBengaliDigits(mins+" মিনিট পরে"):((mins/60)+" ঘণ্টা"+(mins%60==0?"":" "+(mins%60)+" মিনিট")+" পরে");wait=com.sakib.portebo.util.BengaliDateFormat.toBengaliDigits(wait);nextLockdown.setText("পরবর্তী লকডাউন: "+day+" "+period+" "+clock+" ("+wait+")");}
 public void refreshAccess(){if(isAdded()&&toggleLockdown!=null){boolean edit=ParentControlManager.canEdit(requireContext());toggleLockdown.setEnabled(edit);toggleLockdown.setAlpha(edit?1f:.45f);}}
 @Override public void onResume(){super.onResume();refreshAccess();lastNextUpdate=0;refreshApps();h.postDelayed(this::refreshApps,900);updateStatus();h.removeCallbacks(refresh);h.post(refresh);}@Override public void onPause(){h.removeCallbacks(refresh);super.onPause();}
}
